def make_physik_g2():
    # Slightly more advanced, different IDs with 'b' suffix
    base = make_physik_g1()
    result = []
    for line in base:
        line = re.sub(r'id: "ph(\d+)"', lambda m: f'id: "ph{m.group(1)}b"', line)
        result.append(line)
    return result

